// Roofs (P2): the four pieces of plan.md ROOF PIECES, built in the order R3, R1, R2, R5. Each is one roof() call on the
// cottage preset with the dark-slate palette. R2 and R5 go through vocab.roofPiece (attic window, finial). R3 and R1 are
// local: their 3-wide dormers are dropped on these shallow half pitches, so they use 1-wide dormers, and the stock
// spruce fascia and soffit are swapped for dark oak (black accents) to keep the roof dark. Every call dry-runs first.
import { roof } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { roofPiece, ROOF_PALETTE, SMOOTH_SANDSTONE, GLASS_PANE } from "../vocab.mjs";

const DARK_EDGES = { fascia: "dark_oak", soffit: "dark_oak" };
const LOCAL = {
  R3: { footprint: [[0, 6, 12, 19]], o: { style: "gable", ridgeAxis: "x", pitch: "half", overhang: { north: 1, west: 1, south: 1, east: 0 }, maxHeight: 4, gable: SMOOTH_SANDSTONE, edges: DARK_EDGES, dormers: { face: "north", count: 2, style: "gable", width: 1, height: 2, window: GLASS_PANE } } },
  R1: { footprint: [[12, 8, 33, 23], [33, 12, 43, 27]], o: { style: "hip", pitch: "half", overhang: 1, eave: "plain", ridge: "slab", maxHeight: 4, edges: DARK_EDGES, dormers: { face: "south", count: 2, style: "gable", width: 1, height: 2 }, keep: [{ from: [37, 1, 10], to: [39, 14, 12] }] } },
};

function localPiece(g, id) {
  const { footprint, o } = LOCAL[id];
  const opts = { y: 10, material: ROOF_PALETTE, chimneys: [], ...o };
  roof(g, footprint, "cottage", { ...opts, dryRun: true });   // dry run: facts and warnings only, writes nothing
  return roof(g, footprint, "cottage", opts);
}

export function build(g) {
  localPiece(g, "R3");
  localPiece(g, "R1");
  roofPiece(g, "R2", { dryRun: true });
  roofPiece(g, "R2");
  roofPiece(g, "R5", { dryRun: true });
  roofPiece(g, "R5");
}

